/**
 * Outbound HTTP: the analytics service client.
 *
 * `@tsir/link` gives the admin app a typed REST client for outbound calls.
 * The `AnalyticsClient` was generated by `tsir make:link-client`; this module
 * constructs it with a base URL and a host allowlist.
 *
 * The allowlist is the security boundary: a call to a host not in
 * `allowedHosts` is refused at the client layer, before any request is sent.
 */
import { token, valueProvider } from '@tsir/container';
import { AnalyticsClient } from '../clients/analytics.client.ts';

export const analyticsClient = new AnalyticsClient({
  baseUrl: 'https://analytics.local',
  allowedHosts: ['analytics.local'],
});

export const analyticsClientToken = token<AnalyticsClient>('analyticsClient');
export const analyticsClientProvider = valueProvider(analyticsClientToken, analyticsClient);
